-- ================= Vị trí bỏ trống khi nhân sự nghỉ việc + danh sách tỉnh theo khu vực kinh doanh =================
-- Lịch sử người phụ trách địa bàn: khi nghỉ việc / gỡ phân công, vị trí được ghi lại và để TRỐNG
-- (hiện "Trống từ … · trước: …") cho đến khi phân công người mới (closed = 1) hoặc quyết định không tuyển lại.
CREATE TABLE IF NOT EXISTS territory_history (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  territory_id INTEGER NOT NULL REFERENCES territories(id) ON DELETE CASCADE,
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  role TEXT NOT NULL,
  industry TEXT,
  is_concurrent INTEGER NOT NULL DEFAULT 0,
  since TEXT,
  ended_at TEXT NOT NULL DEFAULT (date('now')),
  reason TEXT,                                -- resigned | removed
  closed INTEGER NOT NULL DEFAULT 0,          -- 1 = đã có người mới / không tuyển lại
  filled_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_territory_history_open ON territory_history(closed, territory_id);
CREATE INDEX IF NOT EXISTS idx_territory_history_user ON territory_history(user_id);

-- Mã khu vực theo danh sách của phòng Kinh doanh: Duyên Hải = DHD, Hà Nội = HNC
UPDATE territories SET code = 'DHD' WHERE level = 'area' AND code = 'DH';
UPDATE territories SET code = 'HNC' WHERE level = 'area' AND code = 'HN';
-- Khu vực trải 2 miền: Nam Hà Nội (Miền Bắc; Quảng Bình, Quảng Trị thuộc Miền Trung),
-- Nam Miền Trung (Miền Trung; Bình Phước, Đồng Nai thuộc Miền Nam) → thêm nhánh thứ hai dưới miền còn lại (ASM phụ trách kiêm nhiệm)
INSERT INTO territories(name, code, level, parent_id, sort) SELECT 'Nam Hà Nội (Miền Trung)', 'NHN', 'area', (SELECT id FROM territories WHERE level = 'region' AND name = 'Miền Trung' LIMIT 1), 20
  WHERE (SELECT id FROM territories WHERE level = 'region' AND name = 'Miền Trung' LIMIT 1) IS NOT NULL AND (SELECT id FROM territories WHERE level = 'area' AND code = 'NHN' AND parent_id = (SELECT id FROM territories WHERE level = 'region' AND name = 'Miền Trung' LIMIT 1) LIMIT 1) IS NULL;
INSERT INTO territories(name, code, level, parent_id, sort) SELECT 'Nam Miền Trung (Miền Nam)', 'NMT', 'area', (SELECT id FROM territories WHERE level = 'region' AND name = 'Miền Nam' LIMIT 1), 20
  WHERE (SELECT id FROM territories WHERE level = 'region' AND name = 'Miền Nam' LIMIT 1) IS NOT NULL AND (SELECT id FROM territories WHERE level = 'area' AND code = 'NMT' AND parent_id = (SELECT id FROM territories WHERE level = 'region' AND name = 'Miền Nam' LIMIT 1) LIMIT 1) IS NULL;

-- 63 tỉnh / thành phố (tên trước sáp nhập 2025): tỉnh đã có (kể cả tên viết khác) được chuyển về đúng khu vực,
-- giữ nguyên người phụ trách; chưa có thì thêm mới
