-- TP. Hồ Chí Minh nay thuộc khu vực Đông Nam Bộ: bỏ khu vực "Hồ Chí Minh" mặc định nếu không còn tỉnh / người phụ trách
DELETE FROM territories WHERE level = 'area' AND code = 'HCM'
  AND NOT EXISTS (SELECT 1 FROM territories c WHERE c.parent_id = territories.id)
  AND NOT EXISTS (SELECT 1 FROM territory_members m WHERE m.territory_id = territories.id);
